   172  static int
   173  vips_foreign_load_matrix_header( VipsForeignLoad *load )
   174  {
   175          VipsForeignLoadMatrix *matrix = (VipsForeignLoadMatrix *) load;
   176
   177          char *line;
   178          int width;
   179          int height;
   180          double scale;
   181          double offset;
   182          int result;
   183
   184          /* Rewind.
   185           */
   186          vips_sbuf_unbuffer( matrix->sbuf );
   187          if( vips_source_rewind( matrix->source ) )
   188                  return( -1 );
   189
   190          line = vips_sbuf_get_line_copy( matrix->sbuf );
   191          result = parse_matrix_header( line, &width, &height, &scale, &offset );
   192          g_free( line );
   193          if( result )
   194                  return( -1 );
   195
   196          vips_image_pipelinev( load->out, VIPS_DEMAND_STYLE_THINSTRIP, NULL );
   197          vips_image_init_fields( load->out,
   198                  width, height, 1,
   199                  VIPS_FORMAT_DOUBLE,
   200                  VIPS_CODING_NONE, VIPS_INTERPRETATION_B_W, 1.0, 1.0 );
   201
   202          vips_image_set_double( load->out, "scale", scale );
   203          vips_image_set_double( load->out, "offset", offset );
   204
   205          VIPS_SETSTR( load->out->filename,
   206                  vips_connection_filename( VIPS_CONNECTION( matrix->source ) ) );
   207
   208          if( !(matrix->linebuf = VIPS_ARRAY( NULL, width, double )) )
   209                  return( -1 );
   210
   211          return( 0 );
   212  }
