   214  static int
   215  vips_foreign_load_matrix_load( VipsForeignLoad *load )
   216  {
   217          VipsForeignLoadMatrix *matrix = (VipsForeignLoadMatrix *) load;
   218          VipsObjectClass *class = VIPS_OBJECT_GET_CLASS( load );
   219
   220          int x, y;
   221
   222          vips_image_pipelinev( load->real, VIPS_DEMAND_STYLE_THINSTRIP, NULL );
   223          vips_image_init_fields( load->real,
   224                  load->out->Xsize, load->out->Ysize, 1,
   225                  VIPS_FORMAT_DOUBLE,
   226                  VIPS_CODING_NONE, VIPS_INTERPRETATION_B_W, 1.0, 1.0 );
   227
   228          for( y = 0; y < load->real->Ysize; y++ ) {
   229                  char *line;
   230                  char *p, *q;
   231
   232                  line = vips_sbuf_get_line_copy( matrix->sbuf );
   233
   234                  for( x = 0, p = line;
   235                          (q = vips_break_token( p, " \t" )) &&
   236                                  x < load->out->Xsize;
   237                          x++, p = q )
   238                          if( vips_strtod( p, &matrix->linebuf[x] ) ) {
   239                                  g_free( line );
   240                                  vips_error( class->nickname,
   241                                          _( "bad number \"%s\"" ), p );
   242                                  return( -1 );
   243                          }
   244
   245                  g_free( line );
   246
   247                  if( x != load->out->Xsize ) {
   248                          vips_error( class->nickname,
   249                                  _( "line %d too short" ), y );
   250                          return( -1 );
   251                  }
   252
   253                  if( vips_image_write_line( load->real, y,
   254                          (VipsPel *) matrix->linebuf ) )
   255                          return( -1 );
   256          }
   257
   258          return( 0 );
   259  }
