   261  static void
   262  vips_foreign_load_matrix_class_init( VipsForeignLoadMatrixClass *class )
   263  {
   264          GObjectClass *gobject_class = G_OBJECT_CLASS( class );
   265          VipsObjectClass *object_class = (VipsObjectClass *) class;
   266          VipsForeignLoadClass *load_class = (VipsForeignLoadClass *) class;
   267
   268          gobject_class->dispose = vips_foreign_load_matrix_dispose;
   269
   270          object_class->nickname = "matrixload_base";
   271          object_class->description = _( "load matrix" );
   272          object_class->build = vips_foreign_load_matrix_build;
   273
   274          load_class->get_flags = vips_foreign_load_matrix_get_flags;
   275          load_class->header = vips_foreign_load_matrix_header;
   276          load_class->load = vips_foreign_load_matrix_load;
   277
   278  }
