   308          VipsForeignLoadMatrixFile *file = (VipsForeignLoadMatrixFile *) object;
   309          VipsForeignLoadMatrix *matrix = (VipsForeignLoadMatrix *) object;
   310
   311          if( file->filename )
   312                  if( !(matrix->source =
   313                          vips_source_new_from_file( file->filename )) )
   314                          return( -1 );
   315
   316          if( VIPS_OBJECT_CLASS( vips_foreign_load_matrix_file_parent_class )->
   317                  build( object ) )
   318                  return( -1 );
   319
   320          return( 0 );

